    const context: JobsLogContext = {
      method: 'checkConfiguration',
      service: 'EventhubSdkConfigService',
    };
    if (value === undefined) {
      const configValue = await this.appConfigService.getConfigurationValue(
        'USE_ORDER_ROUTER_ACTOR',
      );
      value = configValue === 'true';
    } else {
      this.customLogger.verbose(
