  private checkConfiguration(): void {
    const context: JobsLogContext = {
      method: 'checkConfiguration',
      service: 'EventhubSdkConfigService',
    };

    // Required configurations for managed identity authentication
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'pickingOrderEventHubName', value: this.eventHubPickingOrderName },
      {
        key: 'pickingOrderEventHubNamespace',
        value: this.eventHubPickingOrderNamespace,
      },
      {
        key: 'pickingOrderStorageAccountName',
        value: this.pickingOrderstorageAccountName,
      },
      {
        key: 'pickingOrderCheckpointInterval',
        value: this.pickingOrdercheckpointInterval,
      },
      {
        key: 'pickingOrdercontainerEventHubName',
        value: this.pickingOrderCheckpointContainerName,
      },
      {
        key: 'shopOrderEventHubNamespace',
        value: this.eventHubShopOrderNamespace,
      },
      {
        key: 'shopOrderStorageAccountName',
        value: this.shopOrderstorageAccountName,
      },
      {
        key: 'shopOrderCheckpointInterval',
        value: this.shopOrderCheckpointContainerName,
      },
      {
        key: 'productionOrderEventHubNamespace',
        value: this.eventHubProductionOrderNamespace,
      },
      {
        key: 'shopOrderStorageAccountName',
        value: this.productionOrderstorageAccountName,
      },
      {
        key: 'shopOrderCheckpointInterval',
        value: this.productionOrderCheckpointContainerName,
      },
      {
        key: 'producerEventHubNamespace',
        value: this.producerEventHubNamespace,
      },
      {
        key: 'producerEventHubName',
        value: this.producerEventHubName,
      },
    ];

    // Check mandatory fields
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.customLogger.debug(
      'All required configurations for direct Event Hub are properly set',
      context,
    );
  }

  /**
   * Get the complete configuration for pickingOrder topic
   * @returns Configuration object with all settings for pickingOrder topic
   */
  public getPickingOrderConfig(): EventHubSdkConfig {
    return {
      checkpointContainerName: this.pickingOrderCheckpointContainerName,
      checkpointInterval: this.pickingOrdercheckpointInterval,
      consumerGroup: this.pickingOrderconsumerGroup,
      eventHubName: this.eventHubPickingOrderName,
      eventHubNamespace: this.eventHubPickingOrderNamespace,
      storageAccountName: this.pickingOrderstorageAccountName,
    };
  }

  /**
   * Get the complete configuration for shopOrder topic
   * @returns Configuration object with all settings for shopOrder topic
   */
  public getShopOrderConfig(): EventHubSdkConfig {
    return {
      checkpointContainerName: this.shopOrderCheckpointContainerName,
      checkpointInterval: this.shopOrdercheckpointInterval,
      consumerGroup: this.shopOrderconsumerGroup,
      eventHubName: this.eventHubShopOrderName,
      eventHubNamespace: this.eventHubShopOrderNamespace,
      storageAccountName: this.shopOrderstorageAccountName,
    };
  }

  /**
   * Get the complete configuration for productionOrder topic
   * @returns Configuration object with all settings for productionOrder topic
   */
  public getProductionOrderConfig(): EventHubSdkConfig {
    return {
      checkpointContainerName: this.productionOrderCheckpointContainerName,
      checkpointInterval: this.productionOrdercheckpointInterval,
      consumerGroup: this.productionOrderconsumerGroup,
      eventHubName: this.eventHubProductionOrderName,
      eventHubNamespace: this.eventHubProductionOrderNamespace,
      storageAccountName: this.productionOrderstorageAccountName,
    };
  }

  /**
   * Helper method to get full config for a  specific topic
   * @param topicName Name of the topic to get config for
   * @returns Complete configuration for the specified topic
   */
  public getTopicConfig(
    topicName: string /* Add more topics as they're added */,
  ): EventHubSdkConfig & {
    checkpointInterval?: number;
    maxRetries?: number;
  } {
    if (topicName === 'pickingOrder') {
      return this.getPickingOrderConfig();
    }

    if (topicName === 'shopOrder') {
      return this.getShopOrderConfig();
    }
    if (topicName === 'productionOrder') {
      return this.getProductionOrderConfig();
    }

    throw new Error(`Configuration for topic ${topicName} not found`);
  }
}

