@Injectable()
export class OrderRouterService {
  public static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: OrderRouterService.name,
      userId,
    };
  }

  public constructor(
    private readonly customLogger: AppLogger,
    private readonly eventHubProducer: EventHubProducerService,
  ) {
    const context = OrderRouterService.createLogContext('constructor');
    this.customLogger.log('Order Router (Event Hub) initialized', context);
  }

  public async publishOrderEvent(message: CombinedDtoWithIndex): Promise<void> {
    await this.publishToEventHub(message);
  }

  /**
   * Publish order event to Event Hub
   * @param message CombinedDtoWithIndex
   * @returns void
   */
  private async publishToEventHub(
    message: CombinedDtoWithIndex,
  ): Promise<void> {
    const context = OrderRouterService.createLogContext('publishToEventHub');
    const plantKey = message.SITE || message.S_SITE;
    const order = message.S_SHOP_ORDER || message.SHOP_ORDER;

