import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { DaprClient } from 'dapr-client';

import { AppLogger } from '@/common/logger/app-logger';
import { RedisConfigService } from '@/config/redis/redis-store/redis-store.service';

@Injectable()
export class ActorActivationService {
  private readonly daprBaseUrl =
    process.env.DAPR_ACTOR_BASE_URL ||
    'http://localhost:3500/v1.0/actors/PlantOrderProcessorActor';

  private readonly actorActivationRateLimit = 30 * 1000; // 30 seconds in milliseconds

  private readonly lastActivationTimes = new Map<string, number>();

  // ✅ Add pending activations tracker to prevent race conditions
  private readonly pendingActivations = new Set<string>();

  private readonly daprClient: DaprClient;

  public constructor(
    private readonly logger: AppLogger,
    private readonly redisConfigService: RedisConfigService,
  ) {
    this.daprClient = new DaprClient();
  }

  /**
   * Checks if enough time has passed since the last activation for the given plant
   * and verifies the actor is not already active or being activated
   * @param plantKey The plant key identifier
   * @param context The logging context
   * @returns true if activation is allowed, false otherwise
   */
  private async shouldActivateActor(
    plantKey: string,
    context: JobsLogContext,
  ): Promise<boolean> {
    // ✅ Check if activation is already in progress (prevents race condition)
    if (this.pendingActivations.has(plantKey)) {
      this.logger.debug(
        `Actor activation already in progress for plant ${plantKey}`,
        context,
      );
      return false;
    }

    // Check rate limiting first (fast in-memory check)
    const now = Date.now();
    const lastActivation = this.lastActivationTimes.get(plantKey);

    if (
      lastActivation &&
      now - lastActivation < this.actorActivationRateLimit
    ) {
      this.logger.verbose(
        `Rate limit not reached for plant ${plantKey}`,
        context,
      );
      return false;
    }

    // Check actor state in Redis
    try {
      const statusKey = `actor:status:${plantKey}`;
      const redisData = await this.daprClient.state.get(
        this.redisConfigService.redisStore,
        statusKey,
      );

      if (!redisData) {
        this.logger.debug(
          `No status found for plant ${plantKey}, allowing activation`,
          context,
        );
        return true;
      }

      const statusValue = redisData.valueOf ? redisData.valueOf() : redisData;
      const isActive =
        (statusValue as { status?: string })?.status === 'active';

      if (isActive) {
        this.logger.verbose(
          `Actor for plant ${plantKey} is already active, skipping activation`,
          context,
        );
        return false;
      }

      return true;
    } catch (error) {
      this.logger.error(
        `Error checking actor status for plant ${plantKey}`,
        context,
        error,
      );
      // On error, allow activation to proceed
      return true;
    }
  }

  /**
   * Generic method to invoke actor methods via the Dapr HTTP API
   * @param actorId The actor ID
   * @param method The method name to invoke
   * @param data The data to pass to the method
   * @param context The logging context
   * @returns Promise with the response from the actor method
   */
  private async invokeActorMethod(
    actorId: string,
    method: string,
    data: Record<string, unknown>,
    context: JobsLogContext,
  ): Promise<Record<string, unknown>> {
    const startTime = Date.now();

    try {
      const url = `${this.daprBaseUrl}/${actorId}/method/${method}`;

      this.logger.debug(
        `Invoking actor method ${method} for ${actorId}`,
        context,
      );

      const response = await fetch(url, {
        body: JSON.stringify(data),
        headers: {
          contentType: 'application/json',
        },
        method: 'POST',
      });

      const duration = Date.now() - startTime;

      if (!response.ok) {
        const errorText = await response.text();
        this.logger.error(
          `Actor method invocation failed: ${response.status} - ${errorText}`,
          context,
        );
        throw new Error(
          `Actor method invocation failed: ${response.status} - ${errorText}`,
        );
      }

      // For methods that return no content
      if (response.status === 204) {
        this.logger.debug(
          `Actor method ${method} completed in ${duration}ms`,
          context,
        );
        return { success: true };
      }

      const responseData = (await response.json()) as Record<string, unknown>;
      this.logger.debug(
        `Actor method ${method} completed in ${duration}ms`,
        context,
      );

      return responseData;
    } catch (error) {
      const duration = Date.now() - startTime;
      this.logger.error(
        `Error invoking actor method ${method} after ${duration}ms`,
        context,
        error,
      );
      throw error;
    }
  }

  /**
   * Activates the plant actor with rate limiting and race condition prevention
   * @param plantKey The plant key identifier
   * @param context The logging context
   * @returns Promise with the response from the actor activation
   */
  public async activatePlantActor(
    plantKey: string,
    context: JobsLogContext,
  ): Promise<Record<string, unknown> | null> {
    // Check rate limiting, state, and pending activations
    if (!(await this.shouldActivateActor(plantKey, context))) {
      this.logger.debug(
        `Actor activation skipped for plant ${plantKey}`,
        context,
      );
      return null;
    }

    // ✅ Mark as pending BEFORE the actual activation (prevents race condition)
    this.pendingActivations.add(plantKey);

    try {
      this.logger.debug(
        `Activating plant actor for plant ${plantKey}`,
        context,
      );

      // Update the last activation time before making the call
      this.lastActivationTimes.set(plantKey, Date.now());

      // Invoke actor activation method
      const result = await this.invokeActorMethod(
        plantKey,
        'activate',
        {
          plantKey,
          timestamp: new Date().toISOString(),
        },
        context,
      );

      this.logger.verbose(
        `Successfully activated plant actor for plant ${plantKey}`,
        context,
      );

      return result;
    } catch (error) {
      this.logger.error(
        `Failed to activate plant actor for plant ${plantKey}`,
        context,
        error,
      );
      // Don't rethrow to avoid breaking the main flow
      return null;
    } finally {
      // ✅ Always remove from pending set after completion (even on error)
      this.pendingActivations.delete(plantKey);
    }
  }
}

