import {
  RedisConnectionService,
  JobsLogContext,
  RedisClientInstance,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';

import { ActorActivationService } from './actor-activation.service';

import { AppLogger } from '@/common/logger/app-logger';
import { CombinedDtoWithIndex } from '@/dapr/dtos/combined.dto';

@Injectable()
export class OrderStreamRouterService {
  public static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: OrderStreamRouterService.name,
      userId,
    };
  }

  public constructor(
    private readonly redisConnectionFactory: RedisConnectionService,
    private readonly customLogger: AppLogger,
    private readonly actorActivationService: ActorActivationService,
  ) {}

  private async executeRedisCommand<T>(
    command: (clientRedis: RedisClientInstance) => Promise<T>,
  ): Promise<T> {
    const client = await this.redisConnectionFactory.getClient();
    try {
      return await command(client);
    } finally {
      await this.redisConnectionFactory.releaseClient(client);
    }
  }

  public async publishOrderEvent(message: CombinedDtoWithIndex): Promise<void> {
    const context =
      OrderStreamRouterService.createLogContext('publishOrderEvent');
    const plantKey = message.SITE || message.S_SITE;
    const order = message.S_SHOP_ORDER || message.SHOP_ORDER;
    if (!plantKey) {
      this.customLogger.warn('Plant key is missing from message', context);
      return;
    }
    const streamKey = `order_stream:${plantKey}`;
    const payload = JSON.stringify(message);
    await this.executeRedisCommand((client) =>
      client.xAdd(streamKey, '*', { payload }),
    );
    this.customLogger.debug(
      `Published order event to Redis stream for order ${order}`,
      context,
    );
    // Activate plant actor with rate limiting
    const actorContext = OrderStreamRouterService.createLogContext(
      'activatePlantActor',
      Number.parseInt(String(plantKey), 10),
      `${plantKey}`,
    );
    // Step 2: Schedule actor activation (NON-BLOCKING)
    setImmediate(async () => {
      try {
        await this.actorActivationService.activatePlantActor(
          String(plantKey),
          actorContext,
        );
      } catch (error) {
        this.customLogger.error(
          `Failed to activate actor for plant ${plantKey}: ${error.message}`,
          context,
        );
      }
    });
    this.customLogger.debug(`after activate plant ${order}`, context);
  }
}

